def maximumWidth(planks):
    # Count how many planks have each height
    cnt = {}
    for h in planks:
        cnt[h] = cnt.get(h, 0) + 1

    vals = list(cnt.keys())
    # pairs_by_sum[S] = max number of disjoint pairs of planks whose heights sum to S
    pairs_by_sum = {}

    for x in range(len(vals)):
        u = vals[x]
        # Two planks of the same height: floor(count / 2) disjoint pairs
        pairs_by_sum[2 * u] = pairs_by_sum.get(2 * u, 0) + cnt[u] // 2
        for y in range(x + 1, len(vals)):
            v = vals[y]
            # Different heights: limited by the scarcer one
            c = cnt[u] if cnt[u] < cnt[v] else cnt[v]
            pairs_by_sum[u + v] = pairs_by_sum.get(u + v, 0) + c

    # A single plank is always a valid fence
    best = 1
    # Target height equal to an original height
    for h in cnt:
        w = cnt[h] + pairs_by_sum.get(h, 0)
        if w > best:
            best = w
    # Target height equal to some pair sum
    for s in pairs_by_sum:
        w = pairs_by_sum[s] + cnt.get(s, 0)
        if w > best:
            best = w
    return best
